// Produk.java
public class Produk {
    String nama;
    int harga;
    int stok;

    Produk(String nama, int harga, int stok) {
        this.nama = nama;
        this.harga = harga;
        this.stok = stok;
    }

    int nilaiStok() {
        return harga * stok;
    }

    String info() {
        return nama + " Rp" + harga + " x" + stok;
    }
}

