// Jam.java
public class Jam {
    int jam;
    int menit;

    Jam() {
        this(0, 0);
    }

    Jam(int jam, int menit) {
        this.jam = jam;
        this.menit = menit;
    }

    void tambahMenit(int tambah) {
        int hari = 24 * 60;
        int total = (jam * 60 + menit + tambah) % hari;
        if (total < 0) {
            total += hari;
        }
        jam = total / 60;
        menit = total % 60;
    }

    String teks() {
        return String.format("%02d:%02d", jam, menit);
    }
}

